/// <reference types="node" />

import { format } from "@yume-chan/lint";
import { writeFileSync } from "node:fs";

let content = `
// Generated by generate-type-tests.js. Do not edit manually.

import type {DeviceMessageParser} from "./impl/index.js";
import type {ScrcpyOptions2_2} from "./options.js";

type Equal<X, Y> =
    (<T>() => T extends X ? 1 : 2) extends <T>() => T extends Y ? 1 : 2
        ? true
        : false;

function expectTrue<T extends true>(value?: T) { void value; }

`;

const controlValues = ["true", "false", "undefined"];
const videoSourceValues = [`"display"`, `"camera"`, "undefined"];

/**
 * @param {string[]} values
 */
function* powerSetExceptEmpty(values) {
    /**
     * @param {number} start
     * @param {string[]} combo
     * @returns {Generator<string[], void, unknown>}
     */
    function* backtrack(start, combo) {
        if (combo.length > 0) {
            yield [...combo];
        }

        for (let i = start; i < values.length; i++) {
            combo.push(values[i]);
            yield* backtrack(i + 1, combo);
            combo.pop();
        }
    }

    yield* backtrack(0, []);
}

/**
 *
 * @param {string[]} control
 * @param {string[]} videoSource
 * @param {boolean[]} expectedType
 * @returns {string}
 */
function generateCase(control, videoSource, expectedType) {
    return `
        expectTrue<
            Equal<
                ScrcpyOptions2_2<{control:${control.join("|")}, videoSource:${videoSource.join("|")}}>["createDeviceMessageParser"],
                ${expectedType.map((expected) => (expected ? `(() => DeviceMessageParser<ScrcpyOptions2_2.Value<{control:${control.join("|")}, videoSource:${videoSource.join("|")}}>>)` : "undefined")).join(" | ")}
            >
        >();
        `.trim();
}

for (const control of powerSetExceptEmpty(controlValues)) {
    content += `\n// #region control: ${control.join(" | ")}\n`;

    for (const videoSource of powerSetExceptEmpty(videoSourceValues)) {
        const controlDefinitelyDisabled =
            (control.length === 1 && control[0] === "false") ||
            (videoSource.length === 1 && videoSource[0] === `"camera"`);
        if (controlDefinitelyDisabled) {
            content += generateCase(control, videoSource, [false]);
            continue;
        }

        const mayDisableControl = videoSource.includes(`"camera"`);
        if (mayDisableControl) {
            content += generateCase(control, videoSource, [true, false]);
            continue;
        }

        const controlMaybeDisabled = control.includes("false");

        content += generateCase(
            control,
            videoSource,
            controlMaybeDisabled ? [true, false] : [true],
        );
    }

    content += `\n// #endregion\n`;
}

content = await format(content, { parser: "typescript", tabWidth: 4 });

writeFileSync(new URL("./type-tests.spec.ts", import.meta.url), content);
